import os,json,time,urllib.request,urllib.error
kind=os.environ['CHECK_KIND']; target=os.environ['CHECK_TARGET']; mode=os.environ['CHECK_MODE']
op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
paths=['/health/ready','/api/learning/catalog','/api/user/me'] if kind=='core-api' else ['/','/index.html']
if mode=='live': paths=([ '/health/ready'] if kind=='core-api' else ['/'])*20
for path in paths:
 expected=401 if path=='/api/user/me' else 200
 req=urllib.request.Request(target+path,headers={'User-Agent':'Pymentor-release-check'})
 started=time.monotonic()
 try:
  with op.open(req,timeout=5) as r: code=r.status; body=r.read(200000)
 except urllib.error.HTTPError as e: code=e.code;body=e.read(200000)
 if code!=expected:raise SystemExit('Release check HTTP status mismatch')
 if time.monotonic()-started>5:raise SystemExit('Release check latency limit')
 if mode=='live':time.sleep(.15)
print('release checks passed',len(paths),kind,mode)
